mapper.select:
select s.suggestion_id, s.evidence_id, s.user_id, p.real_name, s.status, s.summary, s.reviewed_summary, s.confidence, s.generation_mode, s.prompt_version, s.model_name, s.agent_output_json, s.reviewer_id, s.reviewer_name, s.review_comment, s.release_id, s.version, s.create_time, s.resolved_time from expert_profile_update_suggestion s left join expert_profile p on p.user_id = s.user_id
s.status = #{status}
order by s.create_time desc, s.suggestion_id desc

mapper.update:
update expert_profile_update_suggestion_item
set approved_score = #{approvedScore}
where item_id = #{itemId}

update expert_profile_update_suggestion_item
set reviewed_reason = #{reviewedReason}
where item_id = #{itemId}

update expert_profile_update_suggestion
set version = version + 1,
    update_time = sysdate()
where suggestion_id = #{suggestionId}
  and status = 'PENDING'
  and version = #{version}
